(()=>{"use strict";let t=self;t.addEventListener("push",i=>{if(i.data)try{let n=i.data.json(),e={body:n.body,icon:n.icon||"/icon-192x192.png",badge:n.badge||"/icon-192x192.png",data:{url:n.url||"/"}};i.waitUntil(t.registration.showNotification(n.title,e))}catch(e){console.error("Error parseando push data:",e);let n=i.data.text();i.waitUntil(t.registration.showNotification("Alerta de PehueniaGO",{body:n,icon:"/icon-192x192.png",badge:"/icon-192x192.png"}))}}),t.addEventListener("notificationclick",i=>{i.notification.close();let n=i.notification.data?.url||"/";i.waitUntil(t.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t=0;t<i.length;t++){let e=i[t];if(e.url===n&&"focus"in e)return e.focus()}if(t.clients.openWindow)return t.clients.openWindow(n)}))})})();